-- Stagger baseline engagement so trending is not flat.
update public.post_stats s set impressions = 200 + (abs(hashtext(s.post_id::text)) % 800), likes = (abs(hashtext(s.post_id::text)) % 60), saves = (abs(hashtext(s.post_id::text)) % 25), click_outs = (abs(hashtext(s.post_id::text)) % 12);
